"use client";

import { useEffect, useState } from "react";
import { supabase } from "@/lib/supabase";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
// ▼ 修正: Plus をインポートに追加しました ▼
import { Save, Loader2, CalendarDays, Printer, ArrowLeft, Eye, Lock, Edit, Trash2, Plus } from "lucide-react";
import { useAuth } from "@/contexts/AuthContext";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog";
import HaccpPrintHeader from "@/components/HaccpPrintHeader";

// YO-30 の項目定義
// 各セクションのチェック項目と、その選択肢（options）を定義
const TEST_SECTIONS = [
    {
        title: "小箱の状態",
        id: "box",
        items: [
            { id: "box_visual", label: "視覚（目）", options: ["問題ない", "シュリンクに裂け目がある", "傷がある", "凹みがある", "汚れが付着している"] },
            { id: "box_olfactory", label: "嗅覚（鼻）", options: ["問題ない", "異臭がする", "その他"] },
            { id: "box_tactile", label: "触覚（皮膚）", options: ["問題ない", "ざらざらしている", "違和感がある", "その他"] },
        ]
    },
    {
        title: "アルミの状態",
        id: "aluminum",
        items: [
            { id: "alu_visual", label: "視覚（目）", options: ["問題ない", "アルミに裂け目・穴が開いている", "傷がある", "凹みがある", "汚れが付着している"] },
            { id: "alu_olfactory", label: "嗅覚（鼻）", options: ["問題ない", "異臭がする", "その他"] },
            { id: "alu_tactile", label: "触覚（皮膚）", options: ["問題ない", "ざらざらしている", "違和感がある", "その他"] },
        ]
    },
    {
        title: "パンの状態",
        id: "bread",
        items: [
            { id: "bread_visual", label: "視覚（目）", options: ["問題ない", "やや焦げている", "焦げている", "焼けていない", "規格内", "規格外（カップよりはみ出している・少ない・変形している）"] },
            { id: "bread_olfactory", label: "嗅覚（鼻）", options: ["問題ない", "焦げた臭いがする", "酸っぱい香りがする", "異臭がする", "その他"] },
            { id: "bread_gustatory", label: "味覚（舌）", options: ["問題ない", "軽い音がする", "重い音がする", "その他"] }, // 原本に基づくが「味覚」に音が入っているのは元の仕様通りとする
            { id: "bread_tactile", label: "触覚（皮膚）", options: ["問題ない", "ざらざらしている", "違和感がある", "その他"] },
        ]
    }
];

type PlanOption = { lot_code: string; product_name: string };

export default function SensoryTestsPage() {
    const { canEdit } = useAuth();
    const [loading, setLoading] = useState(false);
    const [viewMode, setViewMode] = useState<'input' | 'list'>('list');

    // 日次入力用State
    const [testDate, setTestDate] = useState("");
    const [lotCode, setLotCode] = useState("");
    const [productName, setProductName] = useState("");
    const [results, setResults] = useState<Record<string, string[]>>({});
    const [otherTexts, setOtherTexts] = useState<Record<string, string>>({});
    const [checkerName, setCheckerName] = useState("");
    const [subCheckerName, setSubCheckerName] = useState("");
    const [notes, setNotes] = useState("");
    const [isSaving, setIsSaving] = useState(false);

    // その日製造されたLotのリスト（プルダウン用）
    const [availableLots, setAvailableLots] = useState<PlanOption[]>([]);

    // 一覧用State
    const [testRecords, setTestRecords] = useState<any[]>([]);

    // 印刷・編集用State
    const [printRecord, setPrintRecord] = useState<any>(null);

    // 初期化と一覧取得
    useEffect(() => {
        const today = new Date().toISOString().split('T')[0];
        setTestDate(today);
        fetchRecords();
    }, []);

    // 入力画面で日付が変わった際に、その日の製造計画（Lot）を取得する
    useEffect(() => {
        if (viewMode === 'input' && testDate) fetchAvailableLots(testDate);
    }, [testDate, viewMode]);

    const fetchRecords = async () => {
        setLoading(true);
        const { data } = await supabase.from('sensory_tests').select('*').order('test_date', { ascending: false }).limit(50);
        if (data) setTestRecords(data);
        setLoading(false);
    };

    const fetchAvailableLots = async (dateStr: string) => {
        const { data } = await supabase.from('production_plans')
            .select('lot_code, products(name, variant_name)')
            .eq('production_date', dateStr);

        if (data) {
            const lots = data.map((d: any) => ({
                lot_code: d.lot_code,
                product_name: `${d.products?.name} (${d.products?.variant_name})`
            }));
            setAvailableLots(lots);
        } else {
            setAvailableLots([]);
        }
    };

    // Lot番号が選択されたら、製品名を自動セット
    const handleLotSelect = (selectedLot: string) => {
        setLotCode(selectedLot);
        const target = availableLots.find(l => l.lot_code === selectedLot);
        if (target) setProductName(target.product_name);
        else setProductName("");
    };

    // 新規入力のリセット
    const resetInput = () => {
        const today = new Date().toISOString().split('T')[0];
        setTestDate(today); setLotCode(""); setProductName(""); setCheckerName(""); setSubCheckerName(""); setNotes("");

        // 初期値としてすべての項目を「問題ない」と「規格内」にする
        const initialResults: Record<string, string[]> = {};
        TEST_SECTIONS.forEach(sec => {
            sec.items.forEach(item => {
                initialResults[item.id] = ["問題ない"];
                if (item.id === "bread_visual") initialResults[item.id].push("規格内");
            });
        });
        setResults(initialResults);
        setOtherTexts({});
    };

    const handleOpenInput = () => {
        resetInput();
        setViewMode('input');
    };

    const handleEdit = (record: any) => {
        setTestDate(record.test_date);
        setLotCode(record.lot_code);
        setProductName(record.product_name);
        setCheckerName(record.checker_name || "");
        setSubCheckerName(record.sub_checker_name || "");
        setNotes(record.notes || "");

        const recResults = record.results || {};
        const parsedResults: Record<string, string[]> = {};
        const parsedOthers: Record<string, string> = {};

        // DBに保存されているJSONから、チェック項目と「その他」のテキストを復元
        Object.keys(recResults).forEach(key => {
            if (key.endsWith('_other_text')) {
                parsedOthers[key.replace('_other_text', '')] = recResults[key];
            } else {
                parsedResults[key] = Array.isArray(recResults[key]) ? recResults[key] : [recResults[key]];
            }
        });
        setResults(parsedResults);
        setOtherTexts(parsedOthers);

        setViewMode('input');
    };

    const toggleOption = (itemId: string, option: string) => {
        if (!canEdit) return;
        setResults(prev => {
            const current = prev[itemId] || [];
            let updated = [...current];

            // 「問題ない」等と他の異常項目を排他に扱う（簡易的）
            if (option === "問題ない") {
                const keep = updated.filter(o => o === "規格内" || o === "規格外（カップよりはみ出している・少ない・変形している）");
                updated = ["問題ない", ...keep];
            } else if (option === "規格内" || option === "規格外（カップよりはみ出している・少ない・変形している）") {
                updated = updated.filter(o => o !== "規格内" && o !== "規格外（カップよりはみ出している・少ない・変形している）");
                updated.push(option);
            } else {
                updated = updated.filter(o => o !== "問題ない");
                if (updated.includes(option)) {
                    updated = updated.filter(o => o !== option);
                } else {
                    updated.push(option);
                }
            }
            return { ...prev, [itemId]: updated };
        });
    };

    const handleSave = async () => {
        if (!testDate || !lotCode || !productName) {
            alert("実施日とLot番号（対象品）を選択してください。");
            return;
        }
        setIsSaving(true);

        const saveResults: Record<string, any> = { ...results };
        Object.keys(otherTexts).forEach(key => {
            if (results[key]?.includes("その他") || results[key]?.includes("その他 （ ）")) {
                saveResults[`${key}_other_text`] = otherTexts[key];
            }
        });

        const payload = {
            test_date: testDate,
            product_name: productName,
            lot_code: lotCode,
            results: saveResults,
            checker_name: checkerName,
            sub_checker_name: subCheckerName,
            notes: notes,
            updated_at: new Date().toISOString()
        };

        const { error } = await supabase.from('sensory_tests').upsert(payload, { onConflict: 'test_date,lot_code' });
        setIsSaving(false);
        if (error) {
            alert("保存に失敗しました: " + error.message);
        } else {
            alert("官能検査記録を保存しました！");
            setViewMode('list');
            fetchRecords();
        }
    };

    const handleDelete = async (record: any) => {
        if (!confirm(`Lot: ${record.lot_code} の検査記録を削除しますか？`)) return;
        const { error } = await supabase.from('sensory_tests').delete().eq('id', record.id);
        if (error) alert("削除エラー: " + error.message);
        else fetchRecords();
    };

    // =======================================================================
    // 印刷（PDF帳票）ビュー
    // A4 縦サイズ
    // =======================================================================
    if (printRecord) {
        const rec = printRecord;
        const dObj = new Date(rec.test_date);
        const y = dObj.getFullYear();
        const m = String(dObj.getMonth() + 1).padStart(2, '0');
        const d = String(dObj.getDate()).padStart(2, '0');
        const dayOfWeek = ["日", "月", "火", "水", "木", "金", "土"][dObj.getDay()];

        const pResults = rec.results || {};

        const isChecked = (itemId: string, option: string) => {
            const arr = pResults[itemId] || [];
            return arr.includes(option) ? "☑" : "□";
        };
        const getOtherText = (itemId: string) => pResults[`${itemId}_other_text`] || "　　　　　　　　　　　　　　　　";

        return (
            <div className="bg-slate-200 min-h-screen py-8 print:p-0 print:bg-white flex flex-col items-center">
                <style dangerouslySetInnerHTML={{
                    __html: `
                    @media print {
                        header, nav { display: none !important; }
                        main { padding: 0 !important; margin: 0 !important; max-width: 100% !important; background: white !important; }
                        @page { size: A4 portrait; margin: 15mm; }
                        body { background-color: white !important; color: black !important; }
                        .print-hide { display: none !important; }
                    }
                `}} />

                <div className="w-[210mm] print:w-full flex justify-between mb-4 print-hide">
                    <Button variant="outline" onClick={() => setPrintRecord(null)} className="bg-white text-slate-700 font-bold border-slate-300">
                        <ArrowLeft className="h-4 w-4 mr-2" /> 戻る
                    </Button>
                    <Button onClick={() => window.print()} className="bg-blue-600 hover:bg-blue-700 text-white font-bold shadow-lg">
                        <Printer className="h-5 w-5 mr-2" /> 印刷する (PDFに保存)
                    </Button>
                </div>

                <div className="w-[210mm] min-h-[297mm] bg-white pt-8 pb-10 px-10 print:p-0 shadow-xl print:shadow-none text-black font-sans box-border flex flex-col">

                    <HaccpPrintHeader
                        title="災害備蓄用パン官能検査実施表"
                        docNo="YO-30"
                        establishedDate="2021/4/1"
                        revisedDate="2023/4/1"
                        hasSubChecker={true}
                    />

                    <div className="mb-4 space-y-3 font-medium text-sm">
                        <div className="flex items-end">
                            <div className="w-24">実施日<br /><span className="text-xs">（製造日）</span></div>
                            <div>：　<span className="font-bold underline underline-offset-4 decoration-slate-400">{y}年 {m}月 {d}日</span>　（{dayOfWeek}）</div>
                        </div>
                        <div className="flex items-end">
                            <div className="w-24">実施品目</div>
                            <div>：　<span className="font-bold underline underline-offset-4 decoration-slate-400">{rec.product_name}　（Lot: {rec.lot_code}）</span></div>
                        </div>
                    </div>

                    <table className="w-full border-collapse border-2 border-black text-[13px] flex-1">
                        <tbody>
                            {/* --- 小箱の状態 --- */}
                            <tr><td colSpan={2} className="border border-black text-center py-2 font-bold bg-gray-50">小箱の状態</td><td rowSpan={4} className="border border-black text-xs p-2 align-top w-[20%]">※ 問題があった場合は、詳細を下の記入欄に記載</td></tr>
                            <tr>
                                <td className="border border-black text-center py-3 w-[15%]">視覚（目）</td>
                                <td className="border border-black px-3 py-3 w-[65%] space-y-2">
                                    <div className="flex gap-6"><span>{isChecked("box_visual", "問題ない")} 問題ない</span><span>{isChecked("box_visual", "シュリンクに裂け目がある")} シュリンクに裂け目がある</span></div>
                                    <div className="flex gap-6"><span>{isChecked("box_visual", "傷がある")} 傷がある</span><span>{isChecked("box_visual", "凹みがある")} 凹みがある</span><span>{isChecked("box_visual", "汚れが付着している")} 汚れが付着している</span></div>
                                </td>
                            </tr>
                            <tr>
                                <td className="border border-black text-center py-3">嗅覚（鼻）</td>
                                <td className="border border-black px-3 py-3 space-y-2">
                                    <div className="flex gap-6"><span>{isChecked("box_olfactory", "問題ない")} 問題ない</span><span>{isChecked("box_olfactory", "異臭がする")} 異臭がする</span></div>
                                    <div>{isChecked("box_olfactory", "その他")} その他 （ {getOtherText("box_olfactory")} ）</div>
                                </td>
                            </tr>
                            <tr>
                                <td className="border border-black text-center py-3">触覚（皮膚）</td>
                                <td className="border border-black px-3 py-3 space-y-2">
                                    <div className="flex gap-6"><span>{isChecked("box_tactile", "問題ない")} 問題ない</span><span>{isChecked("box_tactile", "ざらざらしている")} ざらざらしている</span><span>{isChecked("box_tactile", "違和感がある")} 違和感がある</span></div>
                                    <div>{isChecked("box_tactile", "その他")} その他 （ {getOtherText("box_tactile")} ）</div>
                                </td>
                            </tr>

                            {/* --- アルミの状態 --- */}
                            <tr><td colSpan={3} className="border border-black text-center py-2 font-bold bg-gray-50">アルミの状態</td></tr>
                            <tr>
                                <td className="border border-black text-center py-3">視覚（目）</td>
                                <td colSpan={2} className="border border-black px-3 py-3 space-y-2">
                                    <div className="flex gap-6"><span>{isChecked("alu_visual", "問題ない")} 問題ない</span><span>{isChecked("alu_visual", "アルミに裂け目・穴が開いている")} アルミに裂け目・穴が開いている</span></div>
                                    <div className="flex gap-6"><span>{isChecked("alu_visual", "傷がある")} 傷がある</span><span>{isChecked("alu_visual", "凹みがある")} 凹みがある</span><span>{isChecked("alu_visual", "汚れが付着している")} 汚れが付着している</span></div>
                                </td>
                            </tr>
                            <tr>
                                <td className="border border-black text-center py-3">嗅覚（鼻）</td>
                                <td colSpan={2} className="border border-black px-3 py-3 space-y-2">
                                    <div className="flex gap-6"><span>{isChecked("alu_olfactory", "問題ない")} 問題ない</span><span>{isChecked("alu_olfactory", "異臭がする")} 異臭がする</span></div>
                                    <div>{isChecked("alu_olfactory", "その他")} その他 （ {getOtherText("alu_olfactory")} ）</div>
                                </td>
                            </tr>
                            <tr>
                                <td className="border border-black text-center py-3">触覚（皮膚）</td>
                                <td colSpan={2} className="border border-black px-3 py-3 space-y-2">
                                    <div className="flex gap-6"><span>{isChecked("alu_tactile", "問題ない")} 問題ない</span><span>{isChecked("alu_tactile", "ざらざらしている")} ざらざらしている</span><span>{isChecked("alu_tactile", "違和感がある")} 違和感がある</span></div>
                                    <div>{isChecked("alu_tactile", "その他")} その他 （ {getOtherText("alu_tactile")} ）</div>
                                </td>
                            </tr>

                            {/* --- パンの状態 --- */}
                            <tr><td colSpan={3} className="border border-black text-center py-2 font-bold bg-gray-50">パンの状態</td></tr>
                            <tr>
                                <td className="border border-black text-center py-3">視覚（目）</td>
                                <td colSpan={2} className="border border-black px-3 py-3 space-y-2">
                                    <div className="flex gap-6"><span>{isChecked("bread_visual", "問題ない")} 問題ない</span><span>{isChecked("bread_visual", "やや焦げている")} やや焦げている</span><span>{isChecked("bread_visual", "焦げている")} 焦げている</span><span>{isChecked("bread_visual", "焼けていない")} 焼けていない</span></div>
                                    <div className="flex gap-6"><span>{isChecked("bread_visual", "規格内")} 規格内</span><span>{isChecked("bread_visual", "規格外（カップよりはみ出している・少ない・変形している）")} 規格外（カップよりはみ出している・少ない・変形している）</span></div>
                                </td>
                            </tr>
                            <tr>
                                <td className="border border-black text-center py-3">嗅覚（鼻）</td>
                                <td colSpan={2} className="border border-black px-3 py-3 space-y-2">
                                    <div className="flex gap-6"><span>{isChecked("bread_olfactory", "問題ない")} 問題ない</span><span>{isChecked("bread_olfactory", "焦げた臭いがする")} 焦げた臭いがする</span><span>{isChecked("bread_olfactory", "酸っぱい香りがする")} 酸っぱい香りがする</span></div>
                                    <div className="flex gap-6"><span>{isChecked("bread_olfactory", "異臭がする")} 異臭がする</span><span>{isChecked("bread_olfactory", "その他")} その他 （ {getOtherText("bread_olfactory")} ）</span></div>
                                </td>
                            </tr>
                            <tr>
                                <td className="border border-black text-center py-3">味覚（舌）</td>
                                <td colSpan={2} className="border border-black px-3 py-3 space-y-2">
                                    <div className="flex gap-6"><span>{isChecked("bread_gustatory", "問題ない")} 問題ない</span><span>{isChecked("bread_gustatory", "軽い音がする")} 軽い音がする</span><span>{isChecked("bread_gustatory", "重い音がする")} 重い音がする</span></div>
                                    <div>{isChecked("bread_gustatory", "その他")} その他 （ {getOtherText("bread_gustatory")} ）</div>
                                </td>
                            </tr>
                            <tr>
                                <td className="border border-black text-center py-3">触覚（皮膚）</td>
                                <td colSpan={2} className="border border-black px-3 py-3 space-y-2">
                                    <div className="flex gap-6"><span>{isChecked("bread_tactile", "問題ない")} 問題ない</span><span>{isChecked("bread_tactile", "ざらざらしている")} ざらざらしている</span><span>{isChecked("bread_tactile", "違和感がある")} 違和感がある</span></div>
                                    <div>{isChecked("bread_tactile", "その他")} その他 （ {getOtherText("bread_tactile")} ）</div>
                                </td>
                            </tr>
                        </tbody>
                    </table>

                    <div className="mt-2 border-2 border-black flex flex-col min-h-[120px]">
                        <div className="text-center font-bold text-xs py-1 border-b border-black bg-gray-50">・各項目ごとに、チェックをして問題が無いかの確認</div>
                        <div className="p-3 text-sm whitespace-pre-wrap flex-1 leading-[2.5em] bg-[linear-gradient(transparent_95%,#cbd5e1_95%)] bg-[length:100%_2.5em]">
                            {rec.notes || ""}
                        </div>
                    </div>
                </div>
            </div>
        );
    }


    // =======================================================================
    // 通常画面 (一覧 / 入力)
    // =======================================================================
    return (
        <div className="bg-transparent">
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-6">
                <div className="flex items-center gap-4">
                    <h1 className="text-2xl font-bold flex items-center gap-2 text-slate-800">
                        <Eye className="h-6 w-6 text-pink-600" />
                        官能検査実施表 (YO-30)
                    </h1>
                    {!canEdit && <Badge variant="outline" className="bg-slate-100 text-slate-500 border-slate-300 px-3 py-1 shadow-sm hidden md:flex"><Lock className="w-3 h-3 mr-1" /> 閲覧モード</Badge>}
                </div>
                {viewMode === 'list' && canEdit && (
                    <Button onClick={handleOpenInput} className="bg-pink-600 hover:bg-pink-700 text-white font-bold shadow-sm h-10 w-full sm:w-auto">
                        <Plus className="h-4 w-4 mr-2" /> 新規検査を入力
                    </Button>
                )}
                {viewMode === 'input' && (
                    <Button variant="outline" onClick={() => setViewMode('list')} className="font-bold border-slate-300 h-10">
                        <ArrowLeft className="h-4 w-4 mr-2" /> 一覧に戻る
                    </Button>
                )}
            </div>

            {viewMode === 'list' ? (
                <Card className="shadow-sm border-slate-200">
                    <CardHeader className="bg-slate-50 border-b py-4">
                        <CardTitle className="text-lg text-slate-800">検査記録一覧</CardTitle>
                    </CardHeader>
                    <CardContent className="p-0">
                        <div className="overflow-x-auto">
                            <Table className="w-full min-w-[800px] text-sm">
                                <TableHeader className="bg-slate-100">
                                    <TableRow>
                                        <TableHead className="w-28 pl-4">実施(製造)日</TableHead>
                                        <TableHead className="w-48">Lot番号</TableHead>
                                        <TableHead>製品名</TableHead>
                                        <TableHead className="w-48">担当者</TableHead>
                                        <TableHead className="w-40 text-center">アクション</TableHead>
                                    </TableRow>
                                </TableHeader>
                                <TableBody>
                                    {loading ? <TableRow><TableCell colSpan={5} className="h-32 text-center"><Loader2 className="animate-spin h-6 w-6 text-slate-400 mx-auto" /></TableCell></TableRow> : (
                                        testRecords.map(rec => (
                                            <TableRow key={rec.id} className="hover:bg-slate-50">
                                                <TableCell className="pl-4 font-bold text-slate-600">{new Date(rec.test_date).toLocaleDateString()}</TableCell>
                                                <TableCell className="font-black text-pink-700 tracking-widest">{rec.lot_code}</TableCell>
                                                <TableCell className="font-bold text-slate-800">{rec.product_name}</TableCell>
                                                <TableCell className="text-xs text-slate-500">主: {rec.checker_name || "-"}<br />副: {rec.sub_checker_name || "-"}</TableCell>
                                                <TableCell className="text-center">
                                                    <div className="flex justify-center gap-2">
                                                        <Button variant="outline" size="sm" onClick={() => setPrintRecord(rec)} className="h-8 px-2 border-slate-300 hover:bg-slate-100"><Printer className="h-4 w-4" /></Button>
                                                        {canEdit && (
                                                            <>
                                                                <Button variant="outline" size="sm" onClick={() => handleEdit(rec)} className="h-8 px-2 border-blue-200 text-blue-600 hover:bg-blue-50"><Edit className="h-4 w-4" /></Button>
                                                                <Button variant="outline" size="sm" onClick={() => handleDelete(rec)} className="h-8 px-2 border-red-200 text-red-600 hover:bg-red-50"><Trash2 className="h-4 w-4" /></Button>
                                                            </>
                                                        )}
                                                    </div>
                                                </TableCell>
                                            </TableRow>
                                        ))
                                    )}
                                    {testRecords.length === 0 && !loading && (
                                        <TableRow><TableCell colSpan={5} className="text-center py-12 text-slate-500 bg-slate-50">記録がありません。</TableCell></TableRow>
                                    )}
                                </TableBody>
                            </Table>
                        </div>
                    </CardContent>
                </Card>
            ) : (
                <div className="space-y-6 max-w-4xl mx-auto pb-12">
                    <Card className="shadow-sm border-slate-200">
                        <CardHeader className="bg-pink-50/50 border-b pb-4">
                            <CardTitle className="text-lg text-pink-900 flex items-center gap-2">
                                <CalendarDays className="h-5 w-5 text-pink-600" /> 対象Lotの選択
                            </CardTitle>
                        </CardHeader>
                        <CardContent className="pt-6 grid grid-cols-1 sm:grid-cols-2 gap-4">
                            <div>
                                <label className="block text-sm font-bold mb-1 text-slate-700">実施日 (製造日)</label>
                                <Input type="date" value={testDate} onChange={(e) => setTestDate(e.target.value)} className="h-12 text-lg font-bold bg-white border-pink-300 shadow-sm" />
                            </div>
                            <div>
                                <label className="block text-sm font-bold mb-1 text-slate-700">製造Lotを選択 (必須)</label>
                                <select value={lotCode} onChange={(e) => handleLotSelect(e.target.value)} className="w-full h-12 text-base font-bold bg-white border-2 border-pink-300 rounded-md px-3 shadow-sm focus:ring-pink-500">
                                    <option value="">-- この日製造されたLot --</option>
                                    {availableLots.map(l => <option key={l.lot_code} value={l.lot_code}>{l.lot_code} ({l.product_name})</option>)}
                                </select>
                                {availableLots.length === 0 && <p className="text-[10px] text-red-500 mt-1">※この日に製造されたLotはありません。</p>}
                            </div>
                        </CardContent>
                    </Card>

                    {TEST_SECTIONS.map((section) => (
                        <Card key={section.id} className="shadow-sm border-slate-200">
                            <CardHeader className="bg-slate-100 border-b py-3 px-4">
                                <CardTitle className="text-base text-slate-700 font-black">{section.title}</CardTitle>
                            </CardHeader>
                            <CardContent className="p-0">
                                <div className="divide-y divide-slate-100">
                                    {section.items.map((item) => (
                                        <div key={item.id} className="p-4 flex flex-col md:flex-row md:items-start gap-4">
                                            <div className="md:w-32 font-bold text-slate-800 shrink-0 pt-2">{item.label}</div>
                                            <div className="flex-1 flex flex-wrap gap-2">
                                                {item.options.map(opt => {
                                                    const isChecked = results[item.id]?.includes(opt);
                                                    const isOther = opt === "その他" || opt === "その他 （ ）";

                                                    let btnColor = "bg-white border-slate-300 text-slate-600 hover:bg-slate-50";
                                                    if (isChecked) {
                                                        if (opt === "問題ない" || opt === "規格内") btnColor = "bg-blue-100 border-blue-400 text-blue-800 shadow-sm";
                                                        else btnColor = "bg-red-100 border-red-400 text-red-800 shadow-sm"; // 異常
                                                    }

                                                    return (
                                                        <div key={opt} className={`flex items-center gap-2 ${isOther && isChecked ? 'w-full mt-2' : ''}`}>
                                                            <button
                                                                onClick={() => toggleOption(item.id, opt)}
                                                                className={`px-4 py-2 rounded-lg border-2 font-bold text-sm transition-all ${btnColor}`}
                                                            >
                                                                {opt}
                                                            </button>
                                                            {isOther && isChecked && (
                                                                <Input
                                                                    value={otherTexts[item.id] || ""}
                                                                    onChange={e => setOtherTexts(prev => ({ ...prev, [item.id]: e.target.value }))}
                                                                    placeholder="詳細を入力..."
                                                                    className="flex-1 border-red-300 focus-visible:ring-red-400"
                                                                />
                                                            )}
                                                        </div>
                                                    );
                                                })}
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            </CardContent>
                        </Card>
                    ))}

                    <Card className="shadow-sm border-slate-200">
                        <CardContent className="pt-6 space-y-4">
                            <div className="grid grid-cols-2 gap-4">
                                <div><label className="block text-sm font-bold mb-1 text-slate-700">担当者</label><Input value={checkerName} onChange={(e) => setCheckerName(e.target.value)} placeholder="サイン..." /></div>
                                <div><label className="block text-sm font-bold mb-1 text-slate-700">副担当者</label><Input value={subCheckerName} onChange={(e) => setSubCheckerName(e.target.value)} placeholder="サイン..." /></div>
                            </div>
                            <div>
                                <label className="block text-sm font-bold mb-1 text-slate-700">確認・問題があった場合などの詳細</label>
                                <textarea value={notes} onChange={(e) => setNotes(e.target.value)} className="w-full p-3 border border-slate-200 rounded-md text-sm resize-none h-24 bg-white" placeholder="特記事項など..." />
                            </div>
                            <Button onClick={handleSave} disabled={isSaving || !testDate || !lotCode} className="w-full bg-pink-600 hover:bg-pink-700 text-white font-bold h-12 shadow-md mt-4">
                                {isSaving ? <Loader2 className="w-5 h-5 mr-2 animate-spin" /> : <Save className="w-5 h-5 mr-2" />} この検査結果を保存する
                            </Button>
                        </CardContent>
                    </Card>
                </div>
            )}
        </div>
    );
}

"use client";

import { useEffect, useState, useCallback } from "react";
import { supabase } from "@/lib/supabase";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Truck, Loader2, Save, AlertCircle, ArrowRight, Lock, Printer, ArrowLeft, FileText } from "lucide-react";
import { useAuth } from "@/contexts/AuthContext";

type Order = {
  id: string; order_date: string; planned_ship_date: string; desired_ship_date: string;
  quantity: number; status: string; product_id: string; customer_order_no?: string;
  customers?: { name: string };
  products?: { name: string; variant_name: string; unit_per_cs: number };
};
type ProductStock = {
  id: string; lot_code: string; product_id: string; total_pieces: number; expiry_date: string;
  products?: { name: string; variant_name: string; unit_per_cs: number };
};
type Shipment = {
  id: string; order_id: string; ship_date: string; lot_code: string;
  qty_cs: number; qty_piece: number; status: string;
  orders?: {
    product_id: string; desired_ship_date: string; planned_ship_date: string; customer_order_no?: string;
    customers?: { name: string };
    products?: { name: string; variant_name: string; unit_per_cs: number }
  }
};

type OrderGroup = {
  groupId: string; customerOrderNo: string; plannedShipDate: string; desiredShipDate: string;
  customerName: string; items: Order[]; isLate: boolean;
};
type PrintGroup = {
  orderIdPrefix: string; customerName: string; customerOrderNo: string;
  shipDate: string; desiredShipDate: string; shipments: Shipment[];
};

// ============================================================
// ユーティリティ
// ============================================================
function pcsToDisplay(totalPcs: number, unitPerCs: number): { cs: number; p: number } {
  const cs = Math.floor(totalPcs / unitPerCs);
  const remainder = totalPcs % unitPerCs;
  const p = Math.floor(remainder / 2);
  return { cs, p };
}

function displayToPcs(cs: number, p: number, unitPerCs: number): number {
  return (cs * unitPerCs) + (p * 2);
}

export default function ShipmentsPage() {
  const { canEdit } = useAuth();
  const [viewMode, setViewMode] = useState<'list' | 'print'>('list');
  const [loading, setLoading] = useState(true);

  const [orderGroups, setOrderGroups] = useState<OrderGroup[]>([]);
  const [selectedGroup, setSelectedGroup] = useState<OrderGroup | null>(null);

  const [groupedStocks, setGroupedStocks] = useState<Record<string, ProductStock[]>>({});
  const [shipments, setShipments] = useState<Shipment[]>([]);

  const [shipInputs, setShipInputs] = useState<Record<string, { cs: number | ""; p: number | "" }>>({});
  const [shipDate, setShipDate] = useState("");
  const [isOrderCompleted, setIsOrderCompleted] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);

  const fetchOrders = useCallback(async () => {
    setLoading(true);
    const { data } = await supabase.from("orders").select("*, customers(name), products(name, variant_name, unit_per_cs)").in("status", ["received", "in_production"]).order("planned_ship_date", { ascending: true });

    if (data) {
      const groups: Record<string, OrderGroup> = {};
      const today = new Date(); today.setHours(0, 0, 0, 0);

      data.forEach((o: any) => {
        const parts = o.id.split('-');
        const gId = o.customer_order_no
          ? `${o.customer_order_no}_${o.customer_id}_${o.planned_ship_date}`
          : (parts.length > 3 ? parts.slice(0, 3).join('-') : o.id);

        if (!groups[gId]) {
          groups[gId] = {
            groupId: gId, customerOrderNo: o.customer_order_no || "",
            plannedShipDate: o.planned_ship_date || o.desired_ship_date,
            desiredShipDate: o.desired_ship_date, customerName: o.customers?.name || "",
            items: [], isLate: new Date(o.planned_ship_date || o.desired_ship_date) < today
          };
        }
        groups[gId].items.push(o);
      });
      setOrderGroups(Object.values(groups));
    }

    const { data: sData } = await supabase.from("shipments").select("*, orders(product_id, desired_ship_date, planned_ship_date, customer_order_no, customers(name), products(name, variant_name, unit_per_cs))").order("ship_date", { ascending: false }).limit(50);
    if (sData) setShipments(sData as any[]);

    setLoading(false);
  }, []);

  useEffect(() => {
    fetchOrders();
    setShipDate(new Date().toISOString().split('T')[0]);
  }, [fetchOrders]);

  const handleSelectGroup = async (group: OrderGroup) => {
    setSelectedGroup(group);
    setShipInputs({});
    setIsOrderCompleted(true);
    const productIds = group.items.map(i => i.product_id);
    setShipDate(group.plannedShipDate || new Date().toISOString().split('T')[0]);

    const { data, error } = await supabase.from("product_stocks").select("*, products(name, variant_name, unit_per_cs)").in("product_id", productIds).gt("total_pieces", 0).order("expiry_date", { ascending: true });
    if (error) {
      console.error("在庫取得エラー:", error);
      alert("在庫の取得に失敗しました。");
    } else if (data) {
      const gStocks: Record<string, ProductStock[]> = {};
      (data as ProductStock[]).forEach(s => {
        if (!gStocks[s.product_id]) gStocks[s.product_id] = [];
        gStocks[s.product_id].push(s);
      });
      setGroupedStocks(gStocks);
    }
  };

  const handleInputChange = (stockId: string, field: 'cs' | 'p', value: string) => {
    setShipInputs(prev => ({
      ...prev,
      [stockId]: { ...prev[stockId], [field]: value === "" ? "" : Number(value) }
    }));
  };

  const handleSaveShipment = async () => {
    if (!selectedGroup) return;
    const hasInput = Object.values(shipInputs).some(input => (Number(input?.cs) || 0) > 0 || (Number(input?.p) || 0) > 0);
    if (!hasInput) { alert("出荷する数量を入力してください。"); return; }

    setIsProcessing(true);
    try {
      const stockUpdates = [];
      const stockDeletes = [];
      const shipmentInserts = [];
      const historyInserts = [];
      const completedOrderIds = [];

      for (const order of selectedGroup.items) {
        const stocksForProduct = groupedStocks[order.product_id] || [];
        const unitPerCs = order.products?.unit_per_cs || 24;
        let totalShippedForThisOrder = 0;

        for (const stock of stocksForProduct) {
          const input = shipInputs[stock.id];
          const inputCs = Number(input?.cs) || 0;
          const inputP = Number(input?.p) || 0;

          const shipTotalPcs = displayToPcs(inputCs, inputP, unitPerCs);

          if (shipTotalPcs > 0) {
            if (shipTotalPcs > stock.total_pieces) {
              alert(`Lot[${stock.lot_code}] の出荷数(${shipTotalPcs}個)が現在庫(${stock.total_pieces}個)を超えています！`);
              setIsProcessing(false);
              return;
            }

            const newTotalPcs = stock.total_pieces - shipTotalPcs;
            if (newTotalPcs <= 0) {
              stockDeletes.push(stock.id);
            } else {
              // ★修正：エラー回避のため、UPSERT時に必須カラムをすべて含めるようにしました
              stockUpdates.push({
                id: stock.id,
                lot_code: stock.lot_code,
                product_id: stock.product_id,
                expiry_date: stock.expiry_date,
                total_pieces: newTotalPcs
              });
            }

            const random4 = Math.floor(Math.random() * 10000).toString().padStart(4, "0");
            shipmentInserts.push({
              id: `SHP-${shipDate.replace(/-/g, "")}-${random4}`,
              order_id: order.id,
              ship_date: shipDate,
              lot_code: stock.lot_code,
              qty_cs: inputCs,
              qty_piece: inputP,
              status: "shipped"
            });
            historyInserts.push({
              product_id: stock.product_id,
              lot_code: stock.lot_code,
              before_qty: stock.total_pieces,
              after_qty: newTotalPcs,
              reason: `出荷 (${selectedGroup.customerName}様宛)`
            });

            totalShippedForThisOrder += shipTotalPcs;
          }
        }
        if (totalShippedForThisOrder > 0 || isOrderCompleted) completedOrderIds.push(order.id);
      }

      // ★修正：エラーが発生した際に必ず検知（throw）するように修正しました
      if (stockUpdates.length > 0) {
        const { error } = await supabase.from("product_stocks").upsert(stockUpdates, { onConflict: 'id' });
        if (error) throw error;
      }
      if (stockDeletes.length > 0) {
        const { error } = await supabase.from("product_stocks").delete().in('id', stockDeletes);
        if (error) throw error;
      }
      if (shipmentInserts.length > 0) {
        const { error } = await supabase.from("shipments").insert(shipmentInserts);
        if (error) throw error;
      }
      if (historyInserts.length > 0) {
        const { error } = await supabase.from("inventory_adjustments").insert(historyInserts);
        if (error) throw error;
      }

      if (isOrderCompleted && completedOrderIds.length > 0) {
        const { error } = await supabase.from("orders").update({ status: "shipped" }).in("id", completedOrderIds);
        if (error) throw error;
        setSelectedGroup(null);
      } else {
        handleSelectGroup(selectedGroup);
      }

      alert("出荷処理が完了し、在庫から正確に減算されました！");
      fetchOrders();
    } catch (err: any) {
      console.error(err);
      alert("エラー: " + err.message);
    }
    setIsProcessing(false);
  };

  if (viewMode === 'print') {
    const pGroups: Record<string, PrintGroup> = {};

    shipments.forEach(s => {
      const parts = s.order_id.split('-');
      const oPrefix = parts.length > 3 ? parts.slice(0, 3).join('-') : s.order_id;
      const gKey = s.orders?.customer_order_no
        ? `${s.orders.customer_order_no}_${s.ship_date}`
        : `${oPrefix}_${s.ship_date}`;

      if (!pGroups[gKey]) {
        pGroups[gKey] = {
          orderIdPrefix: oPrefix, customerName: s.orders?.customers?.name || "",
          customerOrderNo: s.orders?.customer_order_no || "",
          shipDate: s.ship_date, desiredShipDate: s.orders?.desired_ship_date || "",
          shipments: []
        };
      }
      pGroups[gKey].shipments.push(s);
    });

    const printChunks = Object.values(pGroups);
    const chunkedPages = [];
    for (let i = 0; i < printChunks.length; i += 3) chunkedPages.push(printChunks.slice(i, i + 3));

    return (
      <div className="bg-slate-200 min-h-screen py-8 print:p-0 print:bg-white flex flex-col items-center">
        <style dangerouslySetInnerHTML={{ __html: `@media print { header, nav { display: none !important; } main { padding: 0 !important; margin: 0 !important; max-width: 100% !important; background: white !important; } @page { size: A4 portrait; margin: 10mm; } body { background-color: white !important; color: black !important; } .print-hide { display: none !important; } .page-break { page-break-after: always; } }` }} />
        <div className="w-[210mm] print:w-full flex justify-between mb-4 print-hide">
          <Button variant="outline" onClick={() => setViewMode('list')} className="bg-white text-slate-700 font-bold border-slate-300"><ArrowLeft className="h-4 w-4 mr-2" /> 戻る</Button>
          <div className="flex gap-2">
            <span className="text-sm font-bold bg-white px-3 py-2 rounded border border-slate-300 text-slate-600">※直近の出荷実績から管理票を作成します</span>
            <Button onClick={() => window.print()} className="bg-blue-600 hover:bg-blue-700 text-white font-bold shadow-lg"><Printer className="h-5 w-5 mr-2" /> 印刷する (PDFに保存)</Button>
          </div>
        </div>

        {chunkedPages.length === 0 ? (
          <div className="w-[210mm] bg-white p-8 text-center text-slate-500 font-bold shadow-xl">出力可能な出荷実績がありません</div>
        ) : (
          chunkedPages.map((pageChunks, pageIdx) => (
            <div key={pageIdx} className={`w-[210mm] min-h-[297mm] bg-white p-10 print:p-0 shadow-xl print:shadow-none text-black font-sans box-border flex flex-col justify-between gap-8 ${pageIdx < chunkedPages.length - 1 ? 'page-break mb-8 print:mb-0' : ''}`}>
              {pageChunks.map((group, gIdx) => {
                const productSummary: Record<string, { name: string, variant: string, totalCs: number, totalP: number, lots: Shipment[] }> = {};
                group.shipments.forEach(s => {
                  const pId = s.orders?.product_id || "";
                  if (!productSummary[pId]) {
                    productSummary[pId] = { name: s.orders?.products?.name || "", variant: s.orders?.products?.variant_name || "", totalCs: 0, totalP: 0, lots: [] };
                  }
                  productSummary[pId].totalCs += s.qty_cs;
                  productSummary[pId].totalP += s.qty_piece;
                  productSummary[pId].lots.push(s);
                });
                const rows = Object.values(productSummary);

                return (
                  <div key={gIdx} className="flex-1 flex flex-col border-b-2 border-dashed border-slate-400 pb-6 print:pb-4 last:border-b-0 last:pb-0">
                    <div className="flex justify-between items-end mb-2">
                      <h1 className="text-3xl font-bold tracking-[0.5em] ml-8">出 荷 管 理 票</h1>
                      <table className="border-collapse border border-black text-center text-[10px]">
                        <tbody><tr><th className="border border-black px-2 py-0.5 font-medium">ワークセンターやまびこ</th><th className="border border-black px-2 py-0.5 font-medium">制定日</th><td className="border border-black px-3 py-0.5">2021/4/1</td></tr><tr><th className="border border-black px-2 py-0.5 font-medium">文章No.　　YO-29</th><th className="border border-black px-2 py-0.5 font-medium">改定日</th><td className="border border-black px-3 py-0.5">-</td></tr></tbody>
                      </table>
                    </div>

                    <table className="w-full border-collapse border-2 border-black text-sm mb-2 mt-2">
                      <thead><tr><th className="border border-black py-1 w-[12%] font-medium">出荷日</th><th className="border border-black py-1 w-[12%] font-medium">着予定日</th><th className="border border-black py-1 w-[52%] font-medium">出荷先</th><th className="border border-black py-1 w-[12%] font-medium">施設長</th><th className="border border-black py-1 w-[12%] font-medium">担当</th></tr></thead>
                      <tbody><tr>
                        <td className="border border-black h-12 text-center font-bold text-xs tracking-wider">{new Date(group.shipDate).toLocaleDateString('ja-JP')}</td>
                        <td className="border border-black text-center font-bold text-xs tracking-wider">{new Date(group.desiredShipDate).toLocaleDateString('ja-JP')}</td>
                        <td className="border border-black px-2 font-bold text-base tracking-wide">{group.customerName}</td>
                        <td className="border border-black"></td><td className="border border-black"></td>
                      </tr></tbody>
                    </table>

                    <table className="w-full border-collapse border-2 border-black text-[13px] flex-1 table-fixed">
                      <thead><tr>
                        <th className="border border-black py-1 w-[12%] font-medium">注番</th>
                        <th className="border border-black py-1 w-[15%] font-medium">出荷種類</th>
                        <th className="border border-black py-1 w-[18%] font-medium">LotNo.</th>
                        <th className="border border-black py-1 w-[9%] font-medium">数量</th>
                        <th className="border border-black py-1 w-[18%] font-medium">LotNo.</th>
                        <th className="border border-black py-1 w-[9%] font-medium">数量</th>
                        <th className="border border-black py-1 w-[19%] font-medium text-[11px] leading-tight">種類別 出荷総数</th>
                      </tr></thead>
                      <tbody>
                        {rows.map((row, i) => {
                          const lot1 = row.lots[0];
                          const lot2 = row.lots[1];
                          return (
                            <tr key={i} className="h-6">
                              <td className="border border-black text-center text-[10px] font-bold px-0.5 truncate overflow-hidden whitespace-nowrap">
                                {i === 0 ? (group.customerOrderNo || group.orderIdPrefix.slice(-4)) : ""}
                              </td>
                              <td className="border border-black px-1 font-bold text-[11px] truncate overflow-hidden whitespace-nowrap">{row.variant || row.name}</td>
                              <td className="border border-black text-center font-bold text-[11px] tracking-wider truncate overflow-hidden">{lot1 ? lot1.lot_code : ""}</td>
                              <td className="border border-black text-right pr-1 font-bold leading-none text-xs">{lot1 ? <>{lot1.qty_cs}<span className="text-[9px] font-normal ml-0.5">c/s</span>{lot1.qty_piece > 0 && <span className="text-[9px] font-normal ml-0.5">{lot1.qty_piece}p</span>}</> : ""}</td>
                              <td className="border border-black text-center font-bold text-[11px] tracking-wider truncate overflow-hidden">{lot2 ? lot2.lot_code : ""}</td>
                              <td className="border border-black text-right pr-1 font-bold leading-none text-xs">{lot2 ? <>{lot2.qty_cs}<span className="text-[9px] font-normal ml-0.5">c/s</span>{lot2.qty_piece > 0 && <span className="text-[9px] font-normal ml-0.5">{lot2.qty_piece}p</span>}</> : ""}</td>
                              <td className="border border-black text-center font-black text-sm bg-slate-50 print:bg-transparent">
                                {row.totalCs}<span className="text-[9px] font-normal ml-0.5">c/s</span>
                                {row.totalP > 0 && <span className="ml-1">{row.totalP}<span className="text-[9px] font-normal ml-0.5">p</span></span>}
                              </td>
                            </tr>
                          );
                        })}
                        {Array.from({ length: Math.max(0, 10 - rows.length) }).map((_, i) => (
                          <tr key={`empty-${i}`} className="h-6"><td className="border border-black"></td><td className="border border-black"></td><td className="border border-black"></td><td className="border border-black"></td><td className="border border-black"></td><td className="border border-black"></td><td className="border border-black"></td></tr>
                        ))}
                        <tr><td colSpan={7} className="border border-black h-8 px-2 py-1 text-xs align-top bg-slate-50 print:bg-transparent">備考</td></tr>
                      </tbody>
                    </table>
                  </div>
                );
              })}
              {Array.from({ length: 3 - pageChunks.length }).map((_, idx) => (
                <div key={`empty-${idx}`} className="flex-1 flex flex-col border-b-2 border-dashed border-slate-400 pb-4 last:border-b-0 opacity-10"><div className="w-full h-full border-2 border-black rounded-md"></div></div>
              ))}
            </div>
          ))
        )}
      </div>
    );
  }

  return (
    <div className="bg-transparent">
      <div className="flex justify-between items-center mb-6">
        <div className="flex items-center gap-4">
          <h1 className="text-2xl font-bold flex items-center gap-2 text-slate-800"><Truck className="h-6 w-6 text-blue-600" /> 出荷管理 (引当・実績登録)</h1>
          {!canEdit && <Badge variant="outline" className="bg-slate-100 text-slate-500 border-slate-300 px-3 py-1 shadow-sm hidden md:flex"><Lock className="w-3 h-3 mr-1" /> 閲覧モード</Badge>}
        </div>
        <Button onClick={() => setViewMode('print')} className="bg-slate-800 hover:bg-slate-900 text-white font-bold shadow-sm h-12 md:h-10">
          <FileText className="h-4 w-4 mr-2" /> 出荷実績から管理票(PDF)を作成
        </Button>
      </div>

      <div className="flex flex-col lg:flex-row gap-6">
        {/* 受注グループ選択 */}
        <div className="w-full lg:w-[35%]">
          <h2 className="font-bold text-slate-700 mb-3 flex items-center gap-2">
            <span className="bg-blue-100 text-blue-800 rounded-full w-6 h-6 flex items-center justify-center text-xs">1</span> 出荷予定の注文書を選択
          </h2>
          <div className="space-y-3 h-[calc(100vh-150px)] overflow-y-auto pr-2 pb-10">
            {orderGroups.map((group) => {
              const today = new Date(); today.setHours(0, 0, 0, 0);
              const isLate = new Date(group.plannedShipDate) < today;

              return (
                <Card key={group.groupId} onClick={() => handleSelectGroup(group)} className={`cursor-pointer transition-all border-2 ${selectedGroup?.groupId === group.groupId ? "border-blue-500 bg-blue-50 shadow-md transform scale-[1.02]" : "border-slate-200 hover:border-blue-300"}`}>
                  <CardHeader className="p-4 pb-2 bg-white rounded-t-lg border-b">
                    <div className="flex justify-between items-start mb-2">
                      <div className="flex flex-col">
                        {group.customerOrderNo && <Badge variant="outline" className="w-fit text-[10px] bg-white text-blue-700 font-bold border-blue-200 py-0 mb-1"><FileText className="w-3 h-3 mr-1" />発注: {group.customerOrderNo}</Badge>}
                        <CardTitle className="text-lg text-slate-800 leading-tight">{group.customerName}</CardTitle>
                      </div>
                      <Badge className={`${isLate ? 'bg-red-500 text-white' : 'bg-blue-100 text-blue-800'} border-none shadow-sm text-xs`}>
                        出荷予定: {new Date(group.plannedShipDate).toLocaleDateString()}
                      </Badge>
                    </div>
                  </CardHeader>
                  <CardContent className="p-0 bg-slate-50 rounded-b-lg">
                    <div className="divide-y divide-slate-100">
                      {group.items.map((item) => {
                        const unitPerCs = item.products?.unit_per_cs || 24;
                        // quantity は総個数 → 表示用 cs, p
                        const { cs, p } = pcsToDisplay(item.quantity, unitPerCs);
                        return (
                          <div key={item.id} className="px-4 py-2.5 flex justify-between items-center text-sm bg-white">
                            <div className="font-bold text-slate-700 truncate mr-2">
                              {item.products?.name} <span className="text-xs font-normal text-slate-500">({item.products?.variant_name})</span>
                            </div>
                            <div className="font-black text-lg text-blue-600 shrink-0">
                              {cs} <span className="text-[10px] font-normal text-slate-500">c/s</span>
                              {p > 0 && <span className="text-slate-700 ml-1">{p} <span className="text-[10px] font-normal text-slate-500">p</span></span>}
                            </div>
                          </div>
                        );
                      })}
                    </div>
                  </CardContent>
                </Card>
              );
            })}
            {loading && orderGroups.length === 0 && <div className="text-center py-12"><Loader2 className="animate-spin h-8 w-8 text-slate-400 mx-auto" /></div>}
            {!loading && orderGroups.length === 0 && <div className="text-center py-12 text-slate-500 border border-dashed rounded-lg bg-white">出荷待ちのデータはありません。</div>}
          </div>
        </div>

        {/* 引当入力 */}
        <div className="w-full lg:w-[65%] flex flex-col gap-4">
          <h2 className="font-bold text-slate-700 mb-1 flex items-center gap-2">
            <span className="bg-blue-100 text-blue-800 rounded-full w-6 h-6 flex items-center justify-center text-xs">2</span> 出荷するLotと数量を入力
          </h2>
          <Card className="border-slate-200 shadow-sm overflow-hidden shrink-0">
            {selectedGroup ? (
              <div className="p-0 flex flex-col h-[calc(100vh-180px)]">
                <div className="bg-slate-50 p-4 border-b border-slate-200 shrink-0">
                  <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 mb-2">
                    <div>
                      {selectedGroup.customerOrderNo && <div className="text-xs text-slate-500 font-bold mb-1">発注番号: {selectedGroup.customerOrderNo}</div>}
                      <div className="font-black text-xl text-slate-800">{selectedGroup.customerName}</div>
                      <div className="text-xs font-bold text-slate-500 mt-1">納品(着)予定日: {new Date(selectedGroup.desiredShipDate).toLocaleDateString()}</div>
                    </div>
                    <div className="flex items-center gap-4 bg-white p-2 rounded-lg border shadow-sm">
                      <label className="font-bold text-sm text-blue-800 ml-2">実際の出荷日</label>
                      <Input type="date" value={shipDate} onChange={e => setShipDate(e.target.value)} disabled={!canEdit} className="bg-white w-40 font-bold" />
                    </div>
                  </div>
                </div>

                <div className="overflow-y-auto flex-1 bg-slate-100/50 p-4 space-y-6">
                  {selectedGroup.items.map(order => {
                    const productStocks = groupedStocks[order.product_id] || [];
                    const unitPerCs = order.products?.unit_per_cs || 24;

                    // 注文総個数 → cs, p
                    const { cs: orderCs, p: orderP } = pcsToDisplay(order.quantity, unitPerCs);

                    // 入力済み総個数の合計
                    const totalInputPcs = productStocks.reduce((sum, stock) => {
                      return sum + displayToPcs(Number(shipInputs[stock.id]?.cs) || 0, Number(shipInputs[stock.id]?.p) || 0, unitPerCs);
                    }, 0);
                    const { cs: inputCs, p: inputP } = pcsToDisplay(totalInputPcs, unitPerCs);

                    return (
                      <div key={order.id} className="bg-white border rounded-lg shadow-sm overflow-hidden">
                        <div className="bg-blue-50 border-b border-blue-100 p-3 flex justify-between items-center">
                          <div className="font-bold text-blue-900">{order.products?.name} <span className="text-xs text-blue-600 font-normal">({order.products?.variant_name})</span></div>
                          <div className="flex items-center gap-4">
                            <div className="text-xs font-bold text-slate-500">注文: <span className="text-sm font-black text-slate-800">{orderCs} c/s {orderP > 0 && `${orderP} p`}</span></div>
                            <div className={`text-xs font-bold px-2 py-1 rounded ${totalInputPcs === order.quantity ? 'bg-green-100 text-green-700' : totalInputPcs > 0 ? 'bg-amber-100 text-amber-700' : 'bg-slate-200 text-slate-500'}`}>
                              入力計: {inputCs} c/s {inputP > 0 && `${inputP} p`}
                            </div>
                          </div>
                        </div>

                        <Table className="text-sm">
                          <TableHeader className="bg-slate-50">
                            <TableRow>
                              <TableHead className="pl-4 w-[25%]">Lot番号</TableHead>
                              <TableHead className="w-[20%]">期限</TableHead>
                              <TableHead className="text-right bg-slate-50">現在庫</TableHead>
                              <TableHead className="text-center bg-blue-50 border-l">出荷数入力</TableHead>
                            </TableRow>
                          </TableHeader>
                          <TableBody>
                            {productStocks.map(stock => {
                              // total_pieces は総個数 → 表示用 cs, p
                              const { cs: stockCs, p: stockP } = pcsToDisplay(stock.total_pieces, unitPerCs);

                              const inputCsVal = Number(shipInputs[stock.id]?.cs) || 0;
                              const inputPVal = Number(shipInputs[stock.id]?.p) || 0;
                              // 入力値を総個数に変換して超過判定
                              const inputTotalPcs = displayToPcs(inputCsVal, inputPVal, unitPerCs);

                              const isOver = inputTotalPcs > stock.total_pieces;
                              const isSelected = inputTotalPcs > 0;

                              return (
                                <TableRow key={stock.id} className={`${isSelected ? "bg-blue-50/30" : ""} transition-colors`}>
                                  <TableCell className="font-black text-slate-700 pl-4 tracking-wider">{stock.lot_code}</TableCell>
                                  <TableCell className="text-slate-500 text-xs">{new Date(stock.expiry_date).toLocaleDateString()}</TableCell>
                                  <TableCell className="text-right bg-slate-50/50">
                                    <span className="font-bold text-slate-700">{stockCs} <span className="text-[10px] font-normal">c/s</span></span>
                                    <span className="ml-1 font-bold text-slate-500">{stockP} <span className="text-[9px] font-normal">p</span></span>
                                  </TableCell>
                                  <TableCell className={`border-l p-1 ${isOver ? 'bg-red-50' : 'bg-blue-50/10'}`}>
                                    <div className="flex items-center justify-center gap-1">
                                      {canEdit ? (
                                        <>
                                          <div className="flex items-end">
                                            <Input type="number" min="0" value={shipInputs[stock.id]?.cs ?? ""} onChange={e => handleInputChange(stock.id, 'cs', e.target.value)} className={`w-14 text-right font-bold h-8 px-1 bg-white ${isOver ? 'border-red-400' : 'border-blue-300'}`} />
                                            <span className="text-[10px] text-slate-500 pb-0.5 pl-0.5">c/s</span>
                                          </div>
                                          <div className="flex items-end">
                                            <Input
                                              type="number" min="0"
                                              max={Math.floor((unitPerCs - 1) / 2)}
                                              value={shipInputs[stock.id]?.p ?? ""}
                                              onChange={e => handleInputChange(stock.id, 'p', e.target.value)}
                                              className={`w-12 text-right font-bold h-8 px-1 bg-white ${isOver ? 'border-red-400' : 'border-blue-300'}`}
                                            />
                                            <span className="text-[10px] text-slate-500 pb-0.5 pl-0.5">p</span>
                                          </div>
                                        </>
                                      ) : (<span className="text-xs text-slate-400">権限なし</span>)}
                                    </div>
                                    {isOver && <div className="text-[10px] text-red-600 font-bold text-center mt-1 leading-none">※在庫超過</div>}
                                  </TableCell>
                                </TableRow>
                              );
                            })}
                            {productStocks.length === 0 && (
                              <TableRow><TableCell colSpan={4} className="text-center py-4 text-xs text-slate-400 bg-slate-50">出荷可能な在庫がありません</TableCell></TableRow>
                            )}
                          </TableBody>
                        </Table>
                      </div>
                    );
                  })}
                </div>

                <div className="bg-white border-t p-4 shadow-[0_-4px_10px_rgba(0,0,0,0.05)] shrink-0">
                  {canEdit ? (
                    <div className="flex flex-col sm:flex-row justify-between items-center gap-4">
                      <label className="flex items-center gap-2 cursor-pointer p-2 hover:bg-slate-50 rounded-md border text-sm font-bold text-slate-700">
                        <input type="checkbox" checked={isOrderCompleted} onChange={e => setIsOrderCompleted(e.target.checked)} className="w-4 h-4 text-blue-600 rounded border-slate-300 focus:ring-blue-500" />
                        この注文書全体の出荷を完了(リストから消去)にする
                      </label>
                      <Button
                        onClick={handleSaveShipment}
                        disabled={isProcessing
                          || Object.values(shipInputs).every(i => !i.cs && !i.p)
                          || Object.keys(shipInputs).some(stockId => {
                            const input = shipInputs[stockId];
                            const stock = Object.values(groupedStocks).flat().find(s => s.id === stockId);
                            if (!stock) return false;
                            const unitPerCs = stock.products?.unit_per_cs || 24;
                            return displayToPcs(Number(input.cs) || 0, Number(input.p) || 0, unitPerCs) > stock.total_pieces;
                          })
                        }
                        className="w-full sm:w-auto bg-blue-600 hover:bg-blue-700 text-white font-bold h-12 px-8 shadow-sm"
                      >
                        {isProcessing ? <Loader2 className="w-5 h-5 mr-2 animate-spin" /> : <ArrowRight className="w-5 h-5 mr-2" />}一括で出荷を確定
                      </Button>
                    </div>
                  ) : (
                    <div className="text-slate-500 font-bold text-center"><Lock className="w-4 h-4 inline mr-1" /> 閲覧モードのため出荷処理はできません</div>
                  )}
                </div>
              </div>
            ) : (
              <div className="p-16 text-center text-slate-400 flex flex-col items-center bg-slate-50">
                <Truck className="h-16 w-16 mb-4 opacity-30 text-blue-500 mx-auto" />
                <p className="text-xl font-bold text-slate-500">リストから注文書を選択してください</p>
              </div>
            )}
          </Card>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useState } from "react";
import { supabase } from "@/lib/supabase";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Search, Loader2, Package, Truck, Factory, LineChart, Eye, FileSpreadsheet, Lock, CheckCircle2, AlertCircle } from "lucide-react";
import { useAuth } from "@/contexts/AuthContext";

type TraceResult = {
    lotCode: string;
    productName: string;
    expiryDate: string;
    totalProduced: number; // 個数
    shipments: any[];
    productionPlan: any | null;
    fujiSteamyLogs: any[];
    sensoryTest: any | null;
    boms: any[]; // 使用原料
};

// =======================================================================
// 官能検査結果のキーを日本語に変換するためのマッピング定義
// =======================================================================
const SENSORY_LABELS: Record<string, { category: string, label: string }> = {
    "box_visual": { category: "小箱の状態", label: "視覚（目）" },
    "box_olfactory": { category: "小箱の状態", label: "嗅覚（鼻）" },
    "box_tactile": { category: "小箱の状態", label: "触覚（皮膚）" },
    "alu_visual": { category: "アルミの状態", label: "視覚（目）" },
    "alu_olfactory": { category: "アルミの状態", label: "嗅覚（鼻）" },
    "alu_tactile": { category: "アルミの状態", label: "触覚（皮膚）" },
    "bread_visual": { category: "パンの状態", label: "視覚（目）" },
    "bread_olfactory": { category: "パンの状態", label: "嗅覚（鼻）" },
    "bread_gustatory": { category: "パンの状態", label: "味覚（舌）" },
    "bread_tactile": { category: "パンの状態", label: "触覚（皮膚）" },
};

export default function TraceabilityPage() {
    const { canEdit } = useAuth();
    const [searchLot, setSearchLot] = useState("");
    const [loading, setLoading] = useState(false);
    const [result, setResult] = useState<TraceResult | null>(null);
    const [errorMsg, setErrorMsg] = useState("");

    const handleSearch = async () => {
        if (!searchLot.trim()) return;
        setLoading(true);
        setErrorMsg("");
        setResult(null);

        try {
            // 1. まず製品在庫(product_stocks) または 製造計画(production_plans) から対象Lotを探す
            const { data: stockData } = await supabase.from('product_stocks')
                .select('product_id, expiry_date, products!inner(name, variant_name, unit_per_cs)')
                .eq('lot_code', searchLot)
                .maybeSingle();

            const { data: planData } = await supabase.from('production_plans')
                .select('product_id, production_date, actual_cs, actual_piece, planned_units, products!inner(name, variant_name, unit_per_cs)')
                .eq('lot_code', searchLot)
                .maybeSingle();

            if (!stockData && !planData) {
                setErrorMsg(`Lot番号「${searchLot}」は見つかりませんでした。`);
                setLoading(false);
                return;
            }

            const sProduct = stockData?.products as any;
            const pProduct = planData?.products as any;

            const productId = stockData?.product_id || planData?.product_id;
            const productName = stockData ? `${sProduct.name} (${sProduct.variant_name})` : `${pProduct.name} (${pProduct.variant_name})`;
            const expiryDate = stockData?.expiry_date || "-";
            const unitPerCs = (stockData ? sProduct.unit_per_cs : pProduct.unit_per_cs) || 24;

            // 製造数の算出 (実績があれば実績、なければ計画数)
            let totalProduced = 0;
            if (planData) {
                if (planData.actual_cs !== null) {
                    totalProduced = (planData.actual_cs * unitPerCs) + ((planData.actual_piece || 0) * 2);
                } else {
                    totalProduced = planData.planned_units || 0;
                }
            }

            // 2. 出荷先履歴を検索
            const { data: shipments } = await supabase.from('shipments')
                .select('ship_date, qty_cs, qty_piece, orders(customer_order_no, customers(name))')
                .eq('lot_code', searchLot)
                .order('ship_date', { ascending: false });

            // 3. フジスチーミー記録を検索
            const { data: fujiLogs } = await supabase.from('fuji_steamy_logs')
                .select('*')
                // 計画の製造日と製品IDが一致するものを取得（近似値）
                .eq('work_date', planData?.production_date)
                .eq('product_name', productName.split(' ')[0]);

            // 4. 官能検査結果を検索
            const { data: sensory } = await supabase.from('sensory_tests')
                .select('*')
                .eq('lot_code', searchLot)
                .maybeSingle();

            // 5. BOM（使用原料レシピ）を検索
            const { data: boms } = await supabase.from('bom')
                .select('usage_rate, unit, items(name, item_type)')
                .eq('product_id', productId);

            setResult({
                lotCode: searchLot,
                productName,
                expiryDate,
                totalProduced,
                shipments: shipments || [],
                productionPlan: planData || null,
                fujiSteamyLogs: fujiLogs || [],
                sensoryTest: sensory || null,
                boms: boms || []
            });

        } catch (err: any) {
            console.error(err);
            setErrorMsg("検索中にエラーが発生しました。");
        }
        setLoading(false);
    };

    // =======================================================================
    // 官能検査のJSONデータをパースして、カテゴリ別にグループ化する関数
    // =======================================================================
    const renderSensoryResults = (resultsObj: any) => {
        if (!resultsObj) return null;

        const grouped: Record<string, { label: string, values: string[], other?: string }[]> = {
            "小箱の状態": [],
            "アルミの状態": [],
            "パンの状態": []
        };

        Object.keys(resultsObj).forEach(key => {
            if (key.endsWith('_other_text')) return; // その他テキストは別途処理

            const def = SENSORY_LABELS[key];
            if (def) {
                grouped[def.category].push({
                    label: def.label,
                    values: resultsObj[key],
                    other: resultsObj[`${key}_other_text`]
                });
            }
        });

        return (
            <div className="space-y-4 mt-2">
                {Object.keys(grouped).map(category => (
                    <div key={category} className="border border-slate-200 rounded-lg overflow-hidden">
                        <div className="bg-slate-100 px-3 py-1.5 text-xs font-bold text-slate-700 border-b border-slate-200">
                            {category}
                        </div>
                        <div className="divide-y divide-slate-100 bg-white">
                            {grouped[category].map((item, idx) => {
                                const isProblem = item.values.some(v => v !== "問題ない" && v !== "規格内");
                                return (
                                    <div key={idx} className="px-3 py-2 flex flex-col sm:flex-row sm:items-start gap-1 sm:gap-4 text-xs">
                                        <div className="w-20 font-bold text-slate-500 shrink-0">{item.label}</div>
                                        <div className="flex-1 flex flex-wrap gap-1.5">
                                            {item.values.map((val, vIdx) => {
                                                const isOk = val === "問題ない" || val === "規格内";
                                                return (
                                                    <span key={vIdx} className={`px-2 py-0.5 rounded font-bold ${isOk ? 'bg-blue-50 text-blue-700' : 'bg-red-50 text-red-700 border border-red-200'}`}>
                                                        {val}
                                                    </span>
                                                );
                                            })}
                                            {item.other && <span className="text-red-600 bg-red-50 px-2 py-0.5 rounded border border-red-200">詳細: {item.other}</span>}
                                            {/* 全て問題ない場合のアイコン補足 */}
                                            {!isProblem && <CheckCircle2 className="w-4 h-4 text-blue-500 ml-1" />}
                                            {isProblem && <AlertCircle className="w-4 h-4 text-red-500 ml-1" />}
                                        </div>
                                    </div>
                                );
                            })}
                        </div>
                    </div>
                ))}
            </div>
        );
    };

    return (
        <div className="bg-transparent">
            <div className="flex items-center gap-4 mb-6">
                <h1 className="text-2xl font-bold flex items-center gap-2 text-slate-800">
                    <Search className="h-6 w-6 text-indigo-600" />
                    トレーサビリティ (追跡) 検索
                </h1>
                {!canEdit && <Badge variant="outline" className="bg-slate-100 text-slate-500 border-slate-300 px-3 py-1 shadow-sm"><Lock className="w-3 h-3 mr-1" /> 閲覧モード</Badge>}
            </div>

            <Card className="shadow-sm border-slate-200 mb-8 bg-indigo-50/30">
                <CardContent className="pt-6 pb-6">
                    <div className="max-w-2xl mx-auto flex flex-col sm:flex-row items-center gap-4">
                        <Input
                            value={searchLot}
                            onChange={e => setSearchLot(e.target.value)}
                            onKeyDown={e => { if (e.key === 'Enter') handleSearch(); }}
                            placeholder="追跡したいLot番号を入力... (例: スB26SB)"
                            className="h-14 text-xl font-bold border-indigo-300 shadow-sm bg-white"
                        />
                        <Button
                            onClick={handleSearch}
                            disabled={loading || !searchLot.trim()}
                            className="w-full sm:w-auto h-14 px-8 bg-indigo-600 hover:bg-indigo-700 text-white font-bold text-lg shadow-md shrink-0"
                        >
                            {loading ? <Loader2 className="w-5 h-5 animate-spin mr-2" /> : <Search className="w-5 h-5 mr-2" />}
                            追跡・検索
                        </Button>
                    </div>
                    {errorMsg && <p className="text-center text-red-600 font-bold mt-4">{errorMsg}</p>}
                </CardContent>
            </Card>

            {result && (
                <div className="space-y-6 max-w-5xl mx-auto pb-12">

                    {/* 基本情報 */}
                    <Card className="border-indigo-200 shadow-md overflow-hidden relative">
                        <div className="absolute top-0 left-0 w-2 h-full bg-indigo-600"></div>
                        <CardHeader className="bg-indigo-50/50 border-b pb-4 pl-8">
                            <CardTitle className="text-sm font-bold text-indigo-800 flex items-center gap-2"><Package className="w-4 h-4" /> 製品・Lot基本情報</CardTitle>
                        </CardHeader>
                        <CardContent className="pt-6 pl-8 flex flex-col md:flex-row justify-between gap-6">
                            <div>
                                <div className="text-xs font-bold text-slate-500 mb-1">製品名</div>
                                <div className="text-2xl font-black text-slate-800 leading-tight">{result.productName}</div>
                            </div>
                            <div className="flex gap-8 md:gap-12 flex-wrap">
                                <div>
                                    <div className="text-xs font-bold text-slate-500 mb-1">対象Lot番号</div>
                                    <div className="text-2xl font-black text-indigo-700 tracking-wider">{result.lotCode}</div>
                                </div>
                                <div>
                                    <div className="text-xs font-bold text-slate-500 mb-1">賞味期限</div>
                                    <div className="text-xl font-bold text-slate-700">{result.expiryDate !== "-" ? new Date(result.expiryDate).toLocaleDateString('ja-JP') : "-"}</div>
                                </div>
                                <div>
                                    <div className="text-xs font-bold text-slate-500 mb-1">製造総数 (実績)</div>
                                    <div className="text-xl font-bold text-slate-700">{result.totalProduced > 0 ? `${result.totalProduced} 個` : "-"}</div>
                                </div>
                            </div>
                        </CardContent>
                    </Card>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        {/* 左列：出荷先と使用原料 */}
                        <div className="space-y-6">

                            {/* 出荷履歴 */}
                            <Card className="border-slate-200 shadow-sm">
                                <CardHeader className="bg-slate-50 border-b py-3 px-4">
                                    <CardTitle className="text-sm font-bold text-slate-700 flex items-center gap-2"><Truck className="w-4 h-4 text-purple-600" /> 出荷先履歴 (販売先)</CardTitle>
                                </CardHeader>
                                <CardContent className="p-0">
                                    {result.shipments.length > 0 ? (
                                        <Table className="text-sm">
                                            <TableHeader className="bg-slate-100/50"><TableRow><TableHead>出荷日</TableHead><TableHead>出荷先</TableHead><TableHead className="text-right">数量</TableHead></TableRow></TableHeader>
                                            <TableBody>
                                                {result.shipments.map((s, i) => {
                                                    const orderObj = s.orders as any;
                                                    return (
                                                        <TableRow key={i}>
                                                            <TableCell className="font-bold text-xs">{new Date(s.ship_date).toLocaleDateString('ja-JP')}</TableCell>
                                                            <TableCell>
                                                                <div className="font-bold text-slate-800">{orderObj?.customers?.name || "不明"}</div>
                                                                {orderObj?.customer_order_no && <div className="text-[9px] text-slate-400">発注: {orderObj.customer_order_no}</div>}
                                                            </TableCell>
                                                            <TableCell className="text-right font-bold text-purple-700 whitespace-nowrap">
                                                                {s.qty_cs > 0 && <>{s.qty_cs}<span className="text-[10px] font-normal text-slate-500 ml-0.5">c/s</span></>}
                                                                {s.qty_piece > 0 && <span className="ml-1">{s.qty_piece}<span className="text-[10px] font-normal text-slate-500 ml-0.5">p</span></span>}
                                                            </TableCell>
                                                        </TableRow>
                                                    );
                                                })}
                                            </TableBody>
                                        </Table>
                                    ) : (
                                        <div className="p-6 text-center text-slate-400 text-xs font-bold">まだ出荷されていません</div>
                                    )}
                                </CardContent>
                            </Card>

                            {/* 使用原料 */}
                            <Card className="border-slate-200 shadow-sm">
                                <CardHeader className="bg-slate-50 border-b py-3 px-4">
                                    <CardTitle className="text-sm font-bold text-slate-700 flex items-center gap-2"><Factory className="w-4 h-4 text-amber-600" /> 使用された原材料 (BOM)</CardTitle>
                                </CardHeader>
                                <CardContent className="p-0 max-h-[300px] overflow-y-auto">
                                    {result.boms.length > 0 ? (
                                        <Table className="text-sm">
                                            <TableBody>
                                                {result.boms.filter((b: any) => b.items?.item_type === 'raw_material').map((b: any, i: number) => (
                                                    <TableRow key={i}>
                                                        <TableCell className="font-bold text-slate-700">{b.items?.name}</TableCell>
                                                    </TableRow>
                                                ))}
                                            </TableBody>
                                        </Table>
                                    ) : (
                                        <div className="p-6 text-center text-slate-400 text-xs font-bold">BOM情報がありません</div>
                                    )}
                                </CardContent>
                            </Card>

                        </div>

                        {/* 右列：HACCPと温度記録 */}
                        <div className="space-y-6">

                            {/* 官能検査 */}
                            <Card className="border-slate-200 shadow-sm flex flex-col max-h-[500px]">
                                <CardHeader className="bg-slate-50 border-b py-3 px-4 flex flex-row items-center justify-between shrink-0">
                                    <CardTitle className="text-sm font-bold text-slate-700 flex items-center gap-2"><Eye className="w-4 h-4 text-pink-600" /> 官能検査結果 (YO-30)</CardTitle>
                                    {result.sensoryTest && <Badge className="bg-green-100 text-green-700 shadow-none border-none">実施済</Badge>}
                                </CardHeader>
                                <CardContent className="p-4 overflow-y-auto">
                                    {result.sensoryTest ? (
                                        <div className="space-y-3">
                                            <div className="flex justify-between border-b pb-2 text-xs">
                                                <span className="text-slate-500 font-bold">実施日</span>
                                                <span className="font-bold">{new Date(result.sensoryTest.test_date).toLocaleDateString('ja-JP')}</span>
                                            </div>
                                            <div className="flex justify-between border-b pb-2 text-xs">
                                                <span className="text-slate-500 font-bold">主担当</span>
                                                <span className="font-bold">{result.sensoryTest.checker_name || "不明"}</span>
                                            </div>
                                            {result.sensoryTest.sub_checker_name && (
                                                <div className="flex justify-between border-b pb-2 text-xs">
                                                    <span className="text-slate-500 font-bold">副担当</span>
                                                    <span className="font-bold">{result.sensoryTest.sub_checker_name}</span>
                                                </div>
                                            )}
                                            {/* ▼ 日本語化された検査結果の表示 ▼ */}
                                            {renderSensoryResults(result.sensoryTest.results)}

                                            {result.sensoryTest.notes && (
                                                <div className="mt-3 bg-pink-50/50 p-2 rounded border border-pink-100 text-xs">
                                                    <div className="font-bold text-pink-800 mb-1">備考・特記事項</div>
                                                    <div className="text-slate-700 whitespace-pre-wrap">{result.sensoryTest.notes}</div>
                                                </div>
                                            )}
                                        </div>
                                    ) : (
                                        <div className="py-8 text-center text-red-500 text-xs font-bold bg-red-50 rounded border border-red-100">官能検査が未実施、または見つかりません</div>
                                    )}
                                </CardContent>
                            </Card>

                            {/* フジスチーミー記録 */}
                            <Card className="border-slate-200 shadow-sm">
                                <CardHeader className="bg-slate-50 border-b py-3 px-4">
                                    <CardTitle className="text-sm font-bold text-slate-700 flex items-center gap-2"><LineChart className="w-4 h-4 text-cyan-600" /> フジスチーミー加熱記録</CardTitle>
                                </CardHeader>
                                <CardContent className="p-0">
                                    {result.fujiSteamyLogs.length > 0 ? (
                                        <div className="divide-y divide-slate-100 max-h-[300px] overflow-y-auto">
                                            {result.fujiSteamyLogs.map((log, i) => (
                                                <div key={i} className="p-4 flex justify-between items-center bg-white hover:bg-slate-50 transition-colors">
                                                    <div>
                                                        <div className="text-[10px] text-slate-400 font-mono mb-1">{log.batch_name}</div>
                                                        <div className="text-xs font-bold text-slate-700">開始: {log.start_time.split(' ')[1] || log.start_time}</div>
                                                        <div className="text-xs font-bold text-red-600">80℃: {log.reach_80_time !== "-" ? (log.reach_80_time.split(' ')[1] || log.reach_80_time) : "未達"}</div>
                                                    </div>
                                                    <div className="text-right">
                                                        <div className="text-xl font-black text-slate-800">{log.max_temp} <span className="text-[10px] font-normal text-slate-500">℃ (最高)</span></div>
                                                        <div className="text-xs font-bold text-slate-500">{log.avg_temp} <span className="text-[9px] font-normal">℃ (庫内平均)</span></div>
                                                    </div>
                                                </div>
                                            ))}
                                        </div>
                                    ) : (
                                        <div className="p-6 text-center text-slate-400 text-xs font-bold flex flex-col items-center">
                                            <FileSpreadsheet className="w-8 h-8 mb-2 opacity-30" />
                                            この製造日の加熱記録は見つかりません。<br />CSVがアップロードされていない可能性があります。
                                        </div>
                                    )}
                                </CardContent>
                            </Card>

                        </div>
                    </div>
                </div>
            )}
        </div>
    );
}

